BEGIN;
-- Banner taxonomy is sourced from the canonical mobile An Banner taxonomy. No listing counts are persisted here.
ALTER TABLE banner_listings ADD COLUMN IF NOT EXISTS attributes JSONB NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS banner_reports(
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  reporter_identity_id UUID NOT NULL,
  listing_id BIGINT NOT NULL REFERENCES banner_listings(id) ON DELETE CASCADE,
  reason TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewed','resolved','rejected')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(reporter_identity_id,listing_id)
);
CREATE INDEX IF NOT EXISTS idx_banner_reports_status_created ON banner_reports(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_banner_reports_listing ON banner_reports(listing_id,created_at DESC);
UPDATE banner_categories SET slug='realestate',sort_order=1,active=TRUE WHERE parent_id IS NULL AND name='املاک';
